			}
		}
	} finally {
		Object.defineProperty(Array.prototype, Symbol.iterator, {
			configurable: true,
			value: original,
			writable: true,
		});
	}
	return Object.freeze({ decisionsMatch, memberIterationsAfterOpen });
}

