	if (/\.filter\s*\(\s*\(\{\s*ref\s*\}\)\s*=>\s*ref\.byteLength\s*<=\s*SCANNABLE_BYTES\s*\)/u.test(creatorClose)) {
		sites.push("proposed-head-filter");
	}
	return Object.freeze(sites);
